import {describe, it, expect} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const promptBuilder = new PromptBuilder('test prompt');

function createRejectingProvider(rejection: any): AIProvider {
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw rejection;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const catchRejection = async (call: Promise<unknown>): Promise<any> => {
  try {
    await call;
    return 'resolved without throwing';
  } catch (error) {
    return error;
  }
};

describe('ChatOrchestrator acceptance: Call onError for all rejections', () => {
  // specs/hal-engine-config-hooks/spec.md#1
  it('rejection with string calls onError with Error(cause: string)', async () => {
    let capturedError: any;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        capturedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createRejectingProvider('string boom'), promptBuilder, undefined, {hooks});
    const callerError = await catchRejection(orchestrator.processMessage(createSession('hello')));

    expect(capturedError).toBeInstanceOf(Error);
    expect(capturedError.cause).toBe('string boom');
    expect(callerError).toBe('string boom');
  });

  // specs/hal-engine-config-hooks/spec.md#2
  it('rejection with object calls onError with Error(cause: object)', async () => {
    let capturedError: any;
    const rejection = {code: 'fail', detail: 'object boom'};
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        capturedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createRejectingProvider(rejection), promptBuilder, undefined, {hooks});
    const callerError = await catchRejection(orchestrator.processMessage(createSession('hello')));

    expect(capturedError).toBeInstanceOf(Error);
    expect(capturedError.cause).toBe(rejection);
    expect(callerError).toBe(rejection);
  });

  // specs/hal-engine-config-hooks/spec.md#3
  it('rejection with undefined calls onError with Error(cause: undefined)', async () => {
    let capturedError: any;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        capturedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createRejectingProvider(undefined), promptBuilder, undefined, {hooks});
    const callerError = await catchRejection(orchestrator.processMessage(createSession('hello')));

    expect(capturedError).toBeInstanceOf(Error);
    expect(capturedError.cause).toBe(undefined);
    expect(callerError).toBe(undefined);
  });

  // specs/hal-engine-config-hooks/spec.md#4
  it('rejection with Error instance calls onError with same instance', async () => {
    let capturedError: any;
    const errorInstance = new Error('actual error');
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        capturedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createRejectingProvider(errorInstance), promptBuilder, undefined, {hooks});
    const callerError = await catchRejection(orchestrator.processMessage(createSession('hello')));

    expect(capturedError).toBe(errorInstance);
    expect(callerError).toBe(errorInstance);
  });
});

